const RETRY_HOOK_CHAIN_WARNING_LENGTH = 32;

/**
 * Statuses defined to carry no message body (RFC 7231 §6.3.5, §6.3.6; RFC 7232
 * §4.1). An empty body on one of these is the contract, not a parse failure.
 *
 * @type {Array<number>}
 */
