		{
			return pRequestOptions[pRequestKey];
		}
		if (pRequestOptions && pRequestOptions[pRequestKey] === false)
		{
			return null;
		}
		return (typeof this[pServiceKey] === 'function') ? this[pServiceKey] : null;
