		{
			return Promise.resolve(undefined);
		}
		let tmpInvocation;
		try
		{
			tmpInvocation = Promise.resolve(fHook(pContext));
		}
		catch (pHookError)
		{
			tmpInvocation = Promise.reject(pHookError);
		}
